const initialState = {
    dogs: [],
    allDogs: [],
    temperaments: [],
    details: [],
    orderByName: null,
    
  };
  
  
  function dogReducer(state = initialState, action) {
    switch (action.type) {
      case "ORDER_BY_TEMPERAMENT":
        const allDogs = state.allDogs;
        const statusFiltered =
          action.payload === "All"
            ? allDogs
            : allDogs.filter((el) => el.types.map(typ => typ.name).includes(action.payload));
  
        return {
          ...state,
          dogs: statusFiltered 
        };
      //Its working
      case "GET_NAME":
        return {
          ...state,
          dogs: action.payload,
        };
        case "GET_TEMPERAMENTS":
          return {
            ...state,
            temperaments: action.payload,
          };
       
      //check this later too
      case "GET_ID":
        return {
          ...state,
          // iba a ponerle id pero por las dudas algo ya se llame id y crashee
          details: action.payload,
        };
      //check this as well
      case "POST_DOG":
        return {
          ...state,
        };
      //check this
      case "FILTER_DB":
         const allDogRevenge = state.allDogs;
        /*  console.log(action.payload); */
        const filter2 =
          action.payload === "Created"
            ? allDogRevenge.filter((ele) => ele.createdInDb)
            : allDogRevenge.filter((ele) => !ele.createdInDb);
        return {
          ...state,
          dogs:
            action.payload === "All"
              ? allDogRevenge
              : filter2.length
              ? filter2
              : [],
        }; 
       
        case "RESTORE_DOG":
          return{
              ...state,
              details: []
          }
      case "GET_DOG":
                    
        return {
          ...state,
          dogs: action.payload,
          allDogs: action.payload,
        };
        case "ORDER_BY":
          if (action.payload === "A-Z") {
            return {
              ...state,
              currentPage: 1,
              filtered: [...state.filtered].sort((prev, next) => {
                if (prev.name > next.name) return 1;
                if (prev.name < next.name) return -1;
                return 0;
              }),
            };
          }
    
          if (action.payload === "Z-A") {
            return {
              ...state,
              currentPage: 1,
              filtered: [...state.filtered].sort((prev, next) => {
                if (prev.name > next.name) return -1;
                if (prev.name < next.name) return 1;
                return 0;
              }),
            };
          }
    
          if (action.payload === "desc") {
            return {
              ...state,
              currentPage: 1,
              filtered: [...state.filtered].sort(
                (prev, next) => prev.weight.slice(0, 2) - next.weight.slice(0, 2)
              ),
            };
          }
    
          if (action.payload === "asc") {
            return {
              ...state,
              currentPage: 1,
              filtered: [...state.filtered].sort(
                (prev, next) => next.weight.slice(0, 2) - prev.weight.slice(0, 2)
              ),
            };
          } else {
            return { ...state, filtered: state.dogs };
          }
            
         default:
        return state;
    }
  }
  export default dogReducer;
